(function() {
  'use strict';

  const BAD_WORDS = [
    'porn', 'xxx', 'nude', 'naked', 'nsfw', 'hentai', 'erotic',
    'sex', 'viagra', 'casino', 'bitcoin', 'crypto',
    'hate', 'racism', 'extremist'
  ];

  function checkText(text) {
    if (!text) return false;
    const lower = text.toLowerCase();
    return BAD_WORDS.some(word => lower.includes(word));
  }

  function hideComments() {
    // YouTube comment selectors (may vary)
    const comments = document.querySelectorAll(
      '#comment-text-content, .yt-simple-endpoint.style-scope.yt-formatted-string'
    );

    comments.forEach(comment => {
      try {
        const text = comment.textContent || '';
        if (checkText(text)) {
          // Hide the comment container
          let parent = comment;
          for (let i = 0; i < 10; i++) {
            parent = parent.parentElement;
            if (!parent) break;
            if (parent.getAttribute('data-test-id') === 'comment-item-container') {
              parent.style.display = 'none';
              break;
            }
          }
        }
      } catch (e) {}
    });
  }

  // Initial hide
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hideComments);
  } else {
    hideComments();
  }

  // Monitor for new comments
  const observer = new MutationObserver(hideComments);
  observer.observe(document.body, { childList: true, subtree: true });

  console.log('[SafeNet YouTube Comment Filter] Active');
})();
